INSERT INTO news (category, news_date, title, excerpt, body, addresses, images) VALUES ('Отключения', '2026-08-24', 'Плановое отключение горячей воды на Ленина, 62–70', 'С 26 по 28 августа проводим замену участка розлива ГВС. Холодная вода и отопление работают в обычном режиме.', '["С 26 по 28 августа с 09:00 до 18:00 будет отключено горячее водоснабжение в домах по ул. Ленина, 62, 64, 68, 70.", "Причина — замена изношенного участка розлива горячей воды в подвальных помещениях. Работы выполняются собственной бригадой, подача возобновляется вечером каждого дня после опрессовки.", "Если после включения из крана идёт мутная или ржавая вода — дайте стечь 3–5 минут. Если ситуация не изменилась, оставьте заявку в диспетчерской."]'::jsonb, 'Ленина, 62 · 64 · 68 · 70', '["https://cdn.poehali.dev/projects/7488612f-bc39-44e9-b251-23f2645125bb/files/22b8bcc2-7679-4834-997a-c1e54720c7fe.jpg"]'::jsonb);
INSERT INTO news (category, news_date, title, excerpt, body, addresses, images) VALUES ('Работы', '2026-08-18', 'Завершён ремонт кровли на Косоротова, 11', 'Заменено 340 м² мягкой кровли, обновлены примыкания и воронки внутреннего водостока.', '["Бригада кровельщиков завершила капитальный ремонт мягкой кровли дома по ул. Косоротова, 11. Заменено 340 м² покрытия, восстановлены примыкания к вентшахтам и парапетам, прочищены воронки внутреннего водостока.", "Работы приняты советом дома, акт подписан. Гарантия на выполненные работы — 5 лет.", "Собственникам верхних этажей, у которых ранее фиксировались протечки, просим сообщить о состоянии потолков после первых дождей."]'::jsonb, 'Косоротова, 11', '["https://cdn.poehali.dev/projects/7488612f-bc39-44e9-b251-23f2645125bb/files/658ab32f-a043-4588-a350-234f07734679.jpg", "https://cdn.poehali.dev/projects/7488612f-bc39-44e9-b251-23f2645125bb/files/ca89026e-7b8e-464c-bae3-cf2fdabadf1a.jpg"]'::jsonb);
INSERT INTO news (category, news_date, title, excerpt, body, addresses, images) VALUES ('Объявления', '2026-08-12', 'Подготовка к отопительному сезону: доступ в подвалы и квартиры', 'До 10 сентября проводим опрессовку и промывку систем отопления. Просим обеспечить доступ к стоякам.', '["До 10 сентября во всех домах в управлении проводятся гидравлические испытания и промывка систем отопления — это обязательный этап подготовки к зиме.", "Просим собственников обеспечить доступ к стоякам отопления в квартирах. Если стояк зашит коробом или мебелью, заранее сообщите в диспетчерскую — мастер согласует удобное время.", "График по каждому дому вывешен на информационных стендах в подъездах."]'::jsonb, NULL, '[]'::jsonb);
INSERT INTO news (category, news_date, title, excerpt, body, addresses, images) VALUES ('Отчёты', '2026-07-30', 'Отчёты по домам за первое полугодие 2026 года', 'Опубликованы отчёты о доходах и расходах: сколько собрано, на что израсходовано, что запланировано.', '["В разделе «Раскрытие информации» опубликованы отчёты об исполнении договора управления за первое полугодие 2026 года по каждому дому.", "В отчёте указано: начислено и собрано за содержание жилья, перечень выполненных работ с суммами, остаток средств на конец периода и план работ на второе полугодие.", "Замечания и предложения по отчёту принимаются от совета дома в письменном виде в течение 30 дней."]'::jsonb, NULL, '[]'::jsonb);
INSERT INTO news (category, news_date, title, excerpt, body, addresses, images) VALUES ('Работы', '2026-07-21', 'Обновлено освещение в подъездах пяти домов', 'Установлены светодиодные светильники с датчиками движения — расход электроэнергии на ОДН снизится.', '["В подъездах домов по ул. Точисского, 19, 21 и ул. 5 Июля, 8, 10, 12 заменены светильники на светодиодные с датчиками движения и освещённости.", "Ожидаемое снижение расхода электроэнергии на общедомовые нужды — до 60%, что отразится в квитанциях уже в следующем расчётном периоде.", "О неработающем светильнике сообщайте в диспетчерскую с указанием подъезда и этажа."]'::jsonb, 'Точисского, 19 · 21 · 5 Июля, 8 · 10 · 12', '["https://cdn.poehali.dev/projects/7488612f-bc39-44e9-b251-23f2645125bb/files/ee4802a0-8169-41ca-ac7b-030188303c79.jpg"]'::jsonb);
INSERT INTO news (category, news_date, title, excerpt, body, addresses, images) VALUES ('Объявления', '2026-07-08', 'Показания счётчиков — до 25 числа каждого месяца', 'Передать показания можно через форму на сайте, по телефону диспетчерской или в ГИС ЖКХ.', '["Напоминаем: показания индивидуальных приборов учёта передаются с 20 по 25 число каждого месяца.", "Если показания не переданы вовремя, начисление производится по среднемесячному расходу, а после трёх месяцев — по нормативу с повышающим коэффициентом.", "Удобнее всего передать показания через форму на сайте — они попадают напрямую в расчётный отдел."]'::jsonb, NULL, '[]'::jsonb);